const r = $json;
const pulledAt = new Date().toISOString();

function getAction(actions, type) {
  const a = (actions || []).find(x => x.action_type === type);
  return a ? Number(a.value) : 0;
}

return {
  pulled_at: pulledAt,
  date_start: r.date_start,
  date_stop: r.date_stop,
  ad_account_id: r.account_id,
  currency: r.account_currency,
  level: 'ad',

  campaign_id: r.campaign_id,
  campaign_name: (r.campaign_name || 'Unknown').replace(/'/g, "''"),
  adset_id: r.adset_id,
  adset_name: (r.adset_name || 'Unknown').replace(/'/g, "''"),
  ad_id: r.ad_id,
  ad_name: (r.ad_name || 'Unknown').replace(/'/g, "''"),

  impressions: Number(r.impressions || 0),
  clicks: Number(r.clicks || 0),
  spend: Number(r.spend || 0),

  leads:
    getAction(r.actions, 'lead') +
    getAction(r.actions, 'onsite_conversion.lead_grouped') +
    getAction(r.actions, 'offsite_conversion.fb_pixel_lead'),

  purchases: 0,
  raw_json: JSON.stringify(r).replace(/'/g, "''")
};
